/**
 * Jinx Huntsman + Marionette: rules tests.
 *
 * Wiki: https://wiki.bloodontheclocktower.com/Huntsman
 * Wiki: https://wiki.bloodontheclocktower.com/Marionette
 * (the wiki has no jinx page; each character's page lists the jinx under "Related Jinxes")
 *
 * Generated by `npm run scaffold:rules-tests`, then filled in (L119). Each test quotes the
 * jinx as the wiki words it, word for word, in a `// Wiki: "..."` comment (Trevor, 2026-11-01).
 */
import { describe, expect, it } from 'vitest';
import { findJinx, jinxesAmong } from '#lib/core/data/index.ts';
import { committedGameData } from '#lib/core/testing/committed-data.ts';
import { gainedSetupAbilities } from '#lib/core/rules/gained-abilities.ts';
import { ownJinxRules } from '#lib/core/rules/jinxes.ts';
import { marionetteAs, tableSetup } from './marionette.test-support.ts';

describe('Huntsman + Marionette jinx', () => {
	const data = committedGameData();
	const jinx = findJinx(data.jinxes, 'huntsman', 'marionette');

	it('is in jinxes.json between two official characters', () => {
		expect(data.byId.get('huntsman')?.name).toBe('Huntsman');
		expect(data.byId.get('marionette')?.name).toBe('Marionette');
		expect(jinx).toBeDefined();
		expect(jinx?.reason).not.toBe('');
	});

	it('applies only when both characters are on the script', () => {
		expect(jinxesAmong(data.jinxes, ['huntsman', 'marionette'])).toContain(jinx);
		expect(jinxesAmong(data.jinxes, ['huntsman'])).not.toContain(jinx);
		expect(jinxesAmong(data.jinxes, ['marionette'])).not.toContain(jinx);
	});

	describe('a Marionette who thinks they are the Huntsman means the Damsel was added', () => {
		const withDamsel = ['imp', 'chef', 'empath', 'monk', 'soldier', 'damsel'];
		const base = marionetteAs('huntsman', withDamsel);

		it("is data in the Marionette's rules", () => {
			// Wiki: "If the Marionette thinks that they are the Huntsman, the Damsel was added during setup."
			expect(ownJinxRules(base.game, 'marionette', 'huntsman', base.characters)).toEqual({
				thinksPartnerSetup: true
			});
		});

		it("applies the Huntsman's setup change, so the Damsel fits", () => {
			// Wiki: "the Damsel was added during setup."
			expect(gainedSetupAbilities(base.game, base.characters).map((c) => c.id)).toEqual([
				'huntsman'
			]);
			const codes = tableSetup(base).warnings.map((w) => w.code);
			expect(codes).not.toContain('count-mismatch');
			expect(codes).not.toContain('missing-required');
		});

		it('warns when the Damsel is missing', () => {
			// Wiki: "the Damsel was added during setup."
			const s = marionetteAs('huntsman', ['imp', 'chef', 'empath', 'monk', 'soldier', 'mayor']);
			expect(tableSetup(s).warnings.map((w) => w.code)).toContain('missing-required');
		});

		it('changes nothing with the Huntsman off the script', () => {
			// Wiki: "If the Marionette thinks that they are the Huntsman"
			const off = marionetteAs('huntsman', withDamsel, false);
			expect(gainedSetupAbilities(off.game, off.characters)).toEqual([]);
		});
	});
});
